6|export async function classifyInvoiceText(
7|  text: string,
8|  parsed: ParsedInvoiceData,
9|  registryEntry: SupplierRegistryEntry | null = null
10|): Promise<ClassificationResult> {
11|  // First try specific rules (high confidence for known suppliers)
12|  const rule = classificationRules.find((candidate) => candidate.match(text));
13|  if (rule) {
14|    const result = rule.classify(text, parsed);
15|    // Enrich with registry if available
16|    if (registryEntry) {
17|      return enrichFromRegistry(result, registryEntry);
18|    }
