21|
22|  // Fall back to generic pattern-based classification
23|  const patternResult = classifyByPattern(parsed);
24|
25|  // Enrich with registry if available
26|  if (registryEntry) {
27|    return enrichFromRegistry(patternResult, registryEntry);
28|  }
29|
30|  return patternResult;
