11|// Greek domestic VAT rates
12|const GR_VAT_RATES = new Set([6, 13, 24]);
13|
14|function isEuCountry(countryCode: string): boolean {
15|  return EU_COUNTRIES.has(countryCode.toUpperCase());
16|}
