18|function isGreekVat(vatNumber: string): boolean {
19|  const clean = vatNumber.replace(/\s/g, '').toUpperCase();
20|  return clean.startsWith('EL') || clean.startsWith('GR');
21|}
22|
23|function extractCountryFromVat(vatNumber: string): string {
24|  const clean = vatNumber.replace(/\s/g, '').toUpperCase();
25|  if (clean.length >= 2) return clean.slice(0, 2);
26|  return '';
27|}
