29|function hasGoodsKeywords(parsed: ParsedInvoiceData): boolean {
30|  const goodsKeywords = [
31|    'laptop', 'computer', 'server', 'monitor', 'hardware', 'equipment',
32|    'lenovo', 'dell', 'hp', 'fujitsu', 'thinkpad', 'latitude', 'lifebook', 'probook',
33|    'mouse', 'keyboard', 'printer', 'scanner', 'router', 'switch', 'cable',
