46|export function classifyByPattern(parsed: ParsedInvoiceData): ClassificationResult {
47|  const vat = parsed.supplierVat?.replace(/\s/g, '').toUpperCase() ?? '';
48|  const countryCode = vat.slice(0, 2) || '';
49|  const isEU = isEuCountry(countryCode);
