51|  const hasReverseCharge = parsed.isReverseCharge;
52|  const vatRate = parsed.vatRate ?? 0;
53|
54|  const netAmount = parsed.netAmount || parsed.grossAmount || 0;
55|  const vatAmount = parsed.vatAmount || 0;
56|  const grossAmount = parsed.grossAmount || netAmount + vatAmount;
57|
58|  // EU Services: reverse charge, 0% VAT, EU supplier (not GR)
59|  if (isEU && !isGR && hasReverseCharge && vatRate === 0) {
60|    return {
61|      matchedRuleId: "pattern-eu-service",
62|      confidence: 0.9,
63|      supplierName: parsed.supplierName || "Άγνωστος προμηθευτής",
