83|        netAmount,
84|        vatRate: 0,
85|        vatAmount: 0,
86|        grossAmount,
87|        lineType: InvoiceLineType.services,
88|        expenseCategory: "2.3 Λήψη Υπηρεσιών",
89|        e3Code: "E3_585_010 - Λοιπές Αμοιβές για υπηρεσίες αλλοδαπής",
90|        vatClassification: "365-Φ2 - Ενδοκοινοτικές λήψεις υπηρεσιών άρθρ. 14.2.α",
91|      }],
92|    };
93|  }
94|
95|  // EU Goods: reverse charge, 0% VAT, EU supplier, goods keywords
96|  if (isEU && !isGR && hasReverseCharge && vatRate === 0 && hasGoodsKeywords(parsed)) {
97|    return {
98|      matchedRuleId: "pattern-eu-goods",
99|      confidence: 0.85,
100|      supplierName: parsed.supplierName || "Άγνωστος προμηθευτής",
101|      countryCode,
102|      vatNumber: vat.slice(2),
103|      supplierType: SupplierType.eu_goods,
104|      invoiceKind: InvoiceKind.goods,
