108|      vatClassification: "364-Φ2 - Ενδοκοινοτικές αποκτήσεις αγαθών",
109|      status: InvoiceStatus.parsed,
110|      isReverseCharge: false, // EU goods is not reverse charge in same way
111|      isEu: true,
112|      isDomestic: false,
113|      isNonEu: false,
114|      viesCountryCode: countryCode,
115|      viesVatNumber: vat.slice(2),
116|      viesGoodsAmount: roundMoney(netAmount),
117|      viesServicesAmount: 0,
118|      lines: [{
119|        description: parsed.supplierName || "EU Goods",
120|        netAmount,
121|        vatRate: 0,
122|        vatAmount: 0,
123|        grossAmount,
124|        lineType: InvoiceLineType.goods,
125|        expenseCategory: "2.1 Αγορές Εμπορευμάτων",
126|        e3Code: "E3_102_004 - Αγορές εμπορευμάτων χρήσης Εξωτερικού Ενδοκοινοτικές",
127|        vatClassification: "364-Φ2 - Ενδοκοινοτικές αποκτήσεις αγαθών",
128|      }],
129|    };
130|  }
131|
132|  // Domestic (Greek VAT): GR VAT number, VAT rate 6/13/24%
133|  if ((isGR || GR_VAT_RATES.has(vatRate)) && vatRate > 0) {
134|    return {
135|      matchedRuleId: "pattern-domestic",
136|      confidence: 0.85,
137|      supplierName: parsed.supplierName || "Άγνωστος προμηθευτής",
138|      countryCode: "GR",
139|      vatNumber: vat.replace(/^(GR|EL)/, ''),
140|      supplierType: SupplierType.domestic_services,
141|      invoiceKind: InvoiceKind.services,
142|      myDataInvoiceType: "1.1 Τιμολόγιο Πώλησης Αγαθών/Υπηρεσιών",
143|      expenseCategory: "2.4 Γενικά Έξοδα με δικαίωμα έκπτωσης ΦΠΑ",
144|      e3Code: "E3_585_016 - Λοιπά έξοδα",
145|      vatClassification: "361-Φ2 - Αγορές & δαπάνες στο εσωτερικό της χώρας",
146|      status: InvoiceStatus.parsed,
147|      isReverseCharge: false,
148|      isEu: false,
149|      isDomestic: true,
150|      isNonEu: false,
151|      viesCountryCode: null,
152|      viesVatNumber: null,
153|      viesGoodsAmount: 0,
154|      viesServicesAmount: 0,
155|      lines: [{
156|        description: parsed.supplierName || "Domestic Services",
157|        netAmount,
158|        vatRate,
159|        vatAmount,
160|        grossAmount,
161|        lineType: InvoiceLineType.services,
162|        expenseCategory: "2.4 Γενικά Έξοδα με δικαίωμα έκπτωσης ΦΠΑ",
163|        e3Code: "E3_585_016 - Λοιπά έξοδα",
164|        vatClassification: "361-Φ2 - Αγορές & δαπάνες στο εσωτερικό της χώρας",
165|      }],
166|    };
167|  }
168|
169|  // Non-EU: has VAT number but not EU, or no VAT but clearly foreign
170|  if (vat && !isEU) {
171|    return {
172|      matchedRuleId: "pattern-non-eu",
173|      confidence: 0.7,
174|      supplierName: parsed.supplierName || "Άγνωστος προμηθευτής",
175|      countryCode,
176|      vatNumber: vat.slice(2),
177|      supplierType: SupplierType.non_eu_services,
